package thaumcraft.common.items.casters.foci;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.*;
import thaumcraft.api.aspects.Aspect;
import thaumcraft.api.casters.*;
import thaumcraft.api.items.IArchitect;
import thaumcraft.common.items.casters.*;
public class FocusMediumPlan extends FocusMedium implements IArchitect {
    final Set<BlockPos> checked=new HashSet<>();
    public String getResearch(){return "FOCUSPLAN";}public String getKey(){return "thaumcraft.PLAN";}public int getComplexity(){return 4;}public Aspect getAspect(){return Aspect.CRAFT;}public boolean isExclusive(){return true;}
    public NodeSetting[] createSettings(){return new NodeSetting[]{new NodeSetting("method","focus.plan.method",new NodeSetting.NodeSettingIntList(new int[]{0,1},new String[]{"focus.plan.full","focus.plan.surface"}))};}
    public HitResult[] supplyTargets(){if(getParent()==null||!(getPackage().getCaster() instanceof Player player)||getParent().supplyTrajectories()==null)return new HitResult[0];ItemStack caster=player.getMainHandItem().getItem() instanceof ICaster?player.getMainHandItem():player.getOffhandItem().getItem() instanceof ICaster?player.getOffhandItem():ItemStack.EMPTY;var result=new ArrayList<HitResult>();for(var t:getParent().supplyTrajectories()){var hit=FocusTargeting.block(getPackage().world,player,t.source,t.source.add(t.direction.normalize().scale(16)));if(hit instanceof BlockHitResult block){var positions=getArchitectBlocks(caster,getPackage().world,block.getBlockPos(),block.getDirection(),player);positions.sort(Comparator.comparingDouble(p->p.distSqr(block.getBlockPos())));for(var p:positions)result.add(new BlockHitResult(Vec3.atCenterOf(p),block.getDirection(),p,false));}}return result.toArray(HitResult[]::new);}
    public HitResult getArchitectMOP(ItemStack stack,Level level,LivingEntity player){return FocusTargeting.block(level,player,player.getEyePosition(),player.getEyePosition().add(player.getLookAngle().scale(16)));}public boolean useBlockHighlight(ItemStack stack){return false;}
    public boolean showAxis(ItemStack stack,Level level,Player player,Direction side,EnumAxis axis){if(stack==null||stack.isEmpty())return false;int dimension=CasterManager.getAreaDim(stack);if(getSettingValue("method")==0)return dimension==0||dimension==switch(axis){case X->1;case Z->2;case Y->3;};return switch(side.getAxis()){case Y->axis==EnumAxis.X&&(dimension==0||dimension==1)||axis==EnumAxis.Z&&(dimension==0||dimension==2);case Z->axis==EnumAxis.Y&&(dimension==0||dimension==1)||axis==EnumAxis.X&&(dimension==0||dimension==2);case X->axis==EnumAxis.Y&&(dimension==0||dimension==1)||axis==EnumAxis.Z&&(dimension==0||dimension==2);};}
    public ArrayList<BlockPos> getArchitectBlocks(ItemStack stack,Level level,BlockPos pos,Direction side,Player player){var result=new ArrayList<BlockPos>();if(stack==null||stack.isEmpty())return result;checked.clear();if(getSettingValue("method")==0)checkNeighboursFull(level,pos,pos,side,CasterManager.getAreaX(stack),CasterManager.getAreaY(stack),CasterManager.getAreaZ(stack),result,player);else checkNeighboursSurface(level,pos,level.getBlockState(pos),pos,side,side.getAxis()==Direction.Axis.Z?CasterManager.getAreaZ(stack):CasterManager.getAreaX(stack),CasterManager.getAreaY(stack),side.getAxis()==Direction.Axis.Z?CasterManager.getAreaX(stack):CasterManager.getAreaZ(stack),result,player);return result;}
    public void checkNeighboursFull(Level level,BlockPos origin,BlockPos pos,Direction side,int x,int y,int z,ArrayList<BlockPos> result,Player player){if(!checked.add(pos))return;if(!level.isEmptyBlock(pos))result.add(pos);int minX=origin.getX()-x-x*side.getStepX(),maxX=origin.getX()+x-x*side.getStepX(),minY=origin.getY()-y-y*side.getStepY(),maxY=origin.getY()+y-y*side.getStepY(),minZ=origin.getZ()-z-z*side.getStepZ(),maxZ=origin.getZ()+z-z*side.getStepZ();for(var direction:Direction.values()){var q=pos.relative(direction);if(q.getX()>=minX&&q.getX()<=maxX&&q.getY()>=minY&&q.getY()<=maxY&&q.getZ()>=minZ&&q.getZ()<=maxZ)checkNeighboursFull(level,origin,q,side,x,y,z,result,player);}}
    public void checkNeighboursSurface(Level level,BlockPos origin,BlockState state,BlockPos pos,Direction side,int x,int y,int z,ArrayList<BlockPos> result,Player player){if(!checked.add(pos))return;boolean outside=switch(side.getAxis()){case Y->Math.abs(pos.getX()-origin.getX())>x||Math.abs(pos.getZ()-origin.getZ())>z;case Z->Math.abs(pos.getX()-origin.getX())>x||Math.abs(pos.getY()-origin.getY())>z;case X->Math.abs(pos.getY()-origin.getY())>x||Math.abs(pos.getZ()-origin.getZ())>z;};if(outside)return;if(level.getBlockState(pos)==state&&!state.isAir()&&FocusBlockActions.exposed(level,pos)){result.add(pos);for(var direction:Direction.values())if(direction!=side&&direction!=side.getOpposite())checkNeighboursSurface(level,origin,state,pos.relative(direction),side,x,y,z,result,player);}}
}
